const MARGIN = { top: 8, right: 8, bottom: 8, left: 8 };
const PADDING = 2;
const MAX_STEPS = 2000;
/** Mean glyph advance as a fraction of font size for lowercase sans-serif. */
const CHAR_WIDTH = 0.55;

type PlacedWord = WordCount & { fontSize: number; x: number; y: number };
type Box = { x0: number; y0: number; x1: number; y1: number };

function overlaps(a: Box, b: Box): boolean {
  return a.x0 < b.x1 && a.x1 > b.x0 && a.y0 < b.y1 && a.y1 > b.y0;
}

/**
 * d3-cloud's placement without d3-cloud: walk an Archimedean spiral out from the center
 * until the word's estimated box clears every box already placed. Purely arithmetic, so
 * the same input always yields the same cloud.
 */
function layoutCloud(
  words: WordCount[],
  fontSize: (count: number) => number,
  width: number,
  height: number
): PlacedWord[] {
  const radiusPerRadian = width / 200;
  const probeSpacing = width / 133; // px between successive spiral samples
  const aspect = width / height;
  const boxes: Box[] = [];
  const placed: PlacedWord[] = [];

  for (const word of words) {
    const size = fontSize(word.count);
    const halfWidth = (word.text.length * CHAR_WIDTH * size) / 2 + PADDING;
    const halfHeight = size * 0.45 + PADDING;
    let angle = 1;

    for (let step = 0; step < MAX_STEPS; step++) {
      const x = radiusPerRadian * angle * Math.cos(angle) * aspect;
      const y = radiusPerRadian * angle * Math.sin(angle);
      // Arc length per radian grows with the radius, so shrink the step to keep it even.
      angle += probeSpacing / (radiusPerRadian * angle);

      if (Math.abs(x) + halfWidth > width / 2) continue;
      if (Math.abs(y) + halfHeight > height / 2) continue;

      const box = {
        x0: x - halfWidth,
        y0: y - halfHeight,
        x1: x + halfWidth,
        y1: y + halfHeight
      };
      if (boxes.some((other) => overlaps(box, other))) continue;

      boxes.push(box);
      placed.push({ ...word, fontSize: size, x, y });
      break;
    }
  }
  return placed;
}

/** One row per word; `count` sets the type size and the placement order. */
export type Data = { text: string; count: number }[];

export default function WordCloud({
  data = wordCounts,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.55);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const words = useMemo(
    () => [...data].sort((a, b) => d3.descending(a.count, b.count)),
    [data]
  );

  const fontSize = useMemo(
    () =>
      d3
        .scaleSqrt()
        .domain([0, d3.max(words, (d) => d.count) ?? 1])
        .range([0, innerWidth / 16]),
    [words, innerWidth]
  );

  const placed = useMemo(
    () => layoutCloud(words, fontSize, innerWidth, innerHeight),
    [words, fontSize, innerWidth, innerHeight]
  );

  const color = useMemo(
    () => d3.scaleOrdinal(words.map((d) => d.text), d3.schemeObservable10),
    [words]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Word cloud of the most frequent words in Martin Luther King, Jr.'s I Have a Dream"
    >
      <g fontFamily="sans-serif" textAnchor="middle">
        {placed.map((d) => (
          <text
            key={d.text}
            x={d.x}
            y={d.y}
            fontSize={d.fontSize}
            fill={color(d.text)}
            dominantBaseline="central"
          >
            {d.text}
          </text>
        ))}
      </g>
    </svg>
  );
}
